BEGIN;
-- Links from questions and note chapters to the lessons they belong to.
-- Generated by tools/tag.py. Run after 04_past_questions.sql and
-- 05_notes.sql.
--
-- Lessons are matched by title, not by id: load_curriculum.py generates
-- fresh ids on every run, so a hardcoded id is wrong on any database but
-- the one it came from.
--
-- These tags are a starting point. A teacher moving one is the system
-- working, not failing.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM note_sections WHERE deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Run db/seed/05_notes.sql before this.';
  END IF;
END $$;

