-- Lessons with the most questions behind them, and how many are still
-- waiting on a teacher.
SELECT l.title,
       count(*) FILTER (WHERE ql.is_primary) AS questions,
       count(*) FILTER (WHERE q.needs_review) AS unchecked
FROM question_lessons ql
JOIN lessons l ON l.id = ql.lesson_id
JOIN questions q ON q.id = ql.question_id AND q.deleted_at IS NULL
GROUP BY l.title ORDER BY questions DESC LIMIT 20;
